@push('scripts')<script>document.getElementById('foto-input')?.addEventListener('change',function(){const box=document.getElementById('foto-preview');box.innerHTML='';const files=[...this.files];if(files.length>6){alert('Maksimal 6 foto.');this.value='';return;}files.forEach(file=>{const url=URL.createObjectURL(file);const img=document.createElement('img');img.src=url;img.className='w-full h-24 object-cover rounded-xl border';box.appendChild(img);});});</script>@endpush
